package ru.ascdev.remotehub;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;
public final class HubService extends Service {
 static volatile String status="Подключение…";volatile boolean running;Thread worker;Config cfg;
 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();cfg=new Config(this);getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("hub","Удалённое управление",NotificationManager.IMPORTANCE_LOW));}
 Notification notification(){PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);PendingIntent stop=PendingIntent.getService(this,1,new Intent(this,HubService.class).setAction("STOP"),PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"hub").setSmallIcon(getResources().getIdentifier("ic_hub","drawable",getPackageName())).setContentTitle("ASC Remote Hub").setContentText(status).setContentIntent(open).addAction(new Notification.Action.Builder(null,"Остановить",stop).build()).setOngoing(true).build();}
 void state(String s){if(!running)return;status=s;getSystemService(NotificationManager.class).notify(7,notification());}
 public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"STOP".equals(i.getAction())){cfg.enabled(false);running=false;stopSelf();return START_NOT_STICKY;}if(!cfg.enabled()||!cfg.paired()){stopSelf();return START_NOT_STICKY;}startForeground(7,notification());if(worker==null||!worker.isAlive()){running=true;worker=new Thread(this::loop,"asc-hub");worker.start();}return START_STICKY;}
 boolean active(){return running&&cfg.enabled()&&!Thread.currentThread().isInterrupted();}
 void loop(){int delay=1000;try{String server=cfg.server(),id=cfg.id(),token=cfg.token();Tools tools=new Tools(this);while(active()){try{JSONObject hello=Api.post(server,"/agent/hello",Api.obj("machine_info",tools.info(),"version",Config.VERSION,"tools",Tools.names()),id,token);if(!hello.optBoolean("ok")||!id.equals(hello.optString("device_id")))throw new Exception("Invalid hello");state("Подключено");delay=1000;
 while(active()){JSONObject r=Api.post(server,"/agent/next",new JSONObject(),id,token);if(!active())break;JSONObject j=r.optJSONObject("job");if(j==null)continue;JSONObject result;if(j.optDouble("ttl_seconds",0)<3)result=Tools.error("ExpiredBeforeExecution");else result=tools.handle(j.getString("tool"),j.optJSONObject("arguments"));for(int attempt=0;attempt<3&&active();attempt++){try{Api.post(server,"/agent/result",Api.obj("id",j.getString("id"),"result",result),id,token);break;}catch(Api.Http e){if(e.status==401)throw e;if(e.status<500)break;}catch(Exception e){}if(attempt<2)Thread.sleep(500);}}
 }catch(Api.Http e){if(e.status==401){cfg.enabled(false);state("Привязка отозвана");break;}state("Переподключение");}catch(Exception e){state("Переподключение");}if(active()){Thread.sleep(delay);delay=Math.min(delay*2,30000);}}}catch(Exception e){if(active())state("Подключение остановлено: ошибка ключа");}finally{if(running){running=false;stopSelf();}}}
 public void onDestroy(){running=false;if(worker!=null)worker.interrupt();status="Остановлено";super.onDestroy();}
}